import type { FrameworkApiReference } from '../types'
import { nanobotLearningMeta } from './learning-meta'

type NanobotApiInput = Omit<FrameworkApiReference, 'technologySlug' | 'maturity' | 'officialUrl'> & {
  source: string
  maturity?: FrameworkApiReference['maturity']
}

const docs = 'https://github.com/HKUDS/nanobot/blob/v0.2.2/'

const nanobotApi = ({ source, maturity = 'stable', ...input }: NanobotApiInput): FrameworkApiReference => {
  const learningMeta = nanobotLearningMeta[input.name as keyof typeof nanobotLearningMeta]
  if (!learningMeta) throw new Error(`Missing structured nanobot learning metadata for ${input.name}`)
  return {
    ...input,
    ...learningMeta,
    technologySlug: 'nanobot',
    maturity,
    officialUrl: `${docs}${source}`,
  }
}

